import{_ as r,o as e,c as a,a3 as d}from"./chunks/framework.Ba39LDvt.js";const f=JSON.parse('{"title":"上海 IC 企业地图","description":"从上海产业片区到设计、制造、EDA、IP 与封测企业，按技术方向建立求职检索入口。","frontmatter":{"title":"上海 IC 企业地图","description":"从上海产业片区到设计、制造、EDA、IP 与封测企业，按技术方向建立求职检索入口。"},"headers":[],"relativePath":"career/companies.md","filePath":"career/companies.md","lastUpdated":1795525517000}'),o={name:"career/companies.md"};function h(l,t,n,i,c,s){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="上海-ic-企业地图" tabindex="-1">上海 IC 企业地图 <a class="header-anchor" href="#上海-ic-企业地图" aria-label="Permalink to &quot;上海 IC 企业地图&quot;">​</a></h1><p>上海的集成电路产业覆盖设计、制造、工具、IP、封装与测试。地图的用途是帮助你了解生态与寻找岗位，不是企业排名，也不意味着所列企业当前都有学生岗位。公司可能有多个办公与生产地点，注册地址、总部、面试地点和实际工作地点不能混为一谈。</p><h2 id="先按片区建立空间感" tabindex="-1">先按片区建立空间感 <a class="header-anchor" href="#先按片区建立空间感" aria-label="Permalink to &quot;先按片区建立空间感&quot;">​</a></h2><p>下表只将有公开地址依据的例子放入片区，不把所有公司强行归到张江。</p><table tabindex="0"><thead><tr><th>片区 / 地址线索</th><th>可核实的企业例子</th><th>阅读地图的方法</th></tr></thead><tbody><tr><td>张江 / 浦东</td><td>紫光展锐上海总部、芯原张江总部；华虹相关制造基地</td><td>设计、IP 与制造相互关联，但具体岗位和厂区仍要分别核对</td></tr><tr><td>临港 / 南汇新城</td><td>芯原官网列出的海港大道办公点</td><td>同一企业可能同时在张江与临港有办公点；以具体岗位地址为准</td></tr><tr><td>徐汇漕宝路 / 漕河泾周边</td><td>澜起科技官网列出的漕宝路总部</td><td>不要把“漕河泾周边”当成精确园区边界，面试前核对楼宇</td></tr><tr><td>上海其他园区与多地点</td><td>下表中的设计、EDA 和封测企业</td><td>招聘页面可能按上海市列示，再向招聘方确认实际地点</td></tr></tbody></table><p>片区只能辅助估算通勤与生活安排，不能从“在同一个园区”推断公司之间有合作，也不能从总部地址推断所有实习都在那里。</p><h2 id="设计企业-先理解产品" tabindex="-1">设计企业：先理解产品 <a class="header-anchor" href="#设计企业-先理解产品" aria-label="Permalink to &quot;设计企业：先理解产品&quot;">​</a></h2><table tabindex="0"><thead><tr><th>企业 / 公开品牌</th><th>主要检索方向</th><th>官方入口</th></tr></thead><tbody><tr><td>海思</td><td>芯片与器件设计、连接、感知、视音频和计算</td><td><a href="https://www.hisilicon.com/" target="_blank" rel="noreferrer">海思</a></td></tr><tr><td>紫光展锐（含原展讯相关业务整合后的品牌）</td><td>移动通信、连接与物联网芯片</td><td><a href="https://www.unisoc.com/" target="_blank" rel="noreferrer">紫光展锐</a></td></tr><tr><td>韦尔股份 / 豪威相关业务</td><td>图像传感、模拟与分立器件；投递时核对具体法人和业务</td><td><a href="https://www.willsemi.com/" target="_blank" rel="noreferrer">韦尔</a></td></tr><tr><td>澜起科技</td><td>内存互连等芯片与相关平台</td><td><a href="https://www.montage-tech.com/" target="_blank" rel="noreferrer">澜起</a></td></tr><tr><td>兆芯</td><td>通用处理器与配套芯片</td><td><a href="https://www.zhaoxin.com/" target="_blank" rel="noreferrer">兆芯</a></td></tr><tr><td>沐曦</td><td>GPU 与相关软硬件生态</td><td><a href="https://www.metax-tech.com/" target="_blank" rel="noreferrer">沐曦</a></td></tr><tr><td>壁仞科技</td><td>通用计算与智能计算芯片及系统生态</td><td><a href="https://www.birentech.com/" target="_blank" rel="noreferrer">壁仞</a></td></tr><tr><td>燧原科技</td><td>AI 计算芯片、加速卡与软件平台</td><td><a href="https://www.enflame-tech.com/" target="_blank" rel="noreferrer">燧原</a></td></tr><tr><td>寒武纪上海相关团队</td><td>智能计算芯片与软件生态，地点按具体招聘岗位核对</td><td><a href="https://www.cambricon.com/" target="_blank" rel="noreferrer">寒武纪</a></td></tr></tbody></table><p>同一企业的岗位可能从 RTL、验证和后端延伸到编译器、驱动、性能分析与客户支持。不要看到“GPU 公司”就认为所有职位都在做微架构，也不要把产品宣传中的性能数字当成可直接比较的招聘依据。</p><h2 id="制造、eda、ip-与封测" tabindex="-1">制造、EDA、IP 与封测 <a class="header-anchor" href="#制造、eda、ip-与封测" aria-label="Permalink to &quot;制造、EDA、IP 与封测&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>上海相关企业例子</th><th>可检索的岗位 / 技术</th><th>官方入口</th></tr></thead><tbody><tr><td>晶圆制造</td><td>中芯国际</td><td>工艺、器件、整合、良率、设备、设计服务</td><td><a href="https://www.smics.com/" target="_blank" rel="noreferrer">中芯国际</a></td></tr><tr><td>晶圆制造</td><td>华虹相关制造企业</td><td>特色工艺、器件、制造与可靠性</td><td><a href="https://www.huahonggrace.com/" target="_blank" rel="noreferrer">华虹</a></td></tr><tr><td>EDA</td><td>Cadence 上海相关岗位</td><td>数字 / 模拟设计工具、算法与应用支持</td><td><a href="https://www.cadence.com/" target="_blank" rel="noreferrer">Cadence</a></td></tr><tr><td>EDA</td><td>Synopsys 上海相关岗位</td><td>综合、验证、实现、IP 与应用支持</td><td><a href="https://www.synopsys.com/" target="_blank" rel="noreferrer">Synopsys</a></td></tr><tr><td>EDA</td><td>合见工软</td><td>验证、仿真等工业软件与技术支持</td><td><a href="https://www.univista-isg.com/" target="_blank" rel="noreferrer">合见工软</a></td></tr><tr><td>IP 与设计服务</td><td>芯原股份</td><td>处理器及多媒体 IP、设计、验证与芯片定制</td><td><a href="https://www.verisilicon.com/" target="_blank" rel="noreferrer">芯原</a></td></tr><tr><td>封装测试</td><td>安靠上海相关业务</td><td>封装、测试、工艺、产品与可靠性</td><td><a href="https://amkor.com/" target="_blank" rel="noreferrer">Amkor</a></td></tr><tr><td>封装测试</td><td>日月光上海相关业务</td><td>封装、测试与制造工程</td><td><a href="https://www.aseglobal.com/" target="_blank" rel="noreferrer">ASE</a></td></tr></tbody></table><p>这里只列确定存在的企业与业务入口，不保证当年岗位开放情况。公司更名、重组和产品调整较常见，申请时使用最新招聘名称与签约主体。</p><h2 id="从公司清单到投递清单" tabindex="-1">从公司清单到投递清单 <a class="header-anchor" href="#从公司清单到投递清单" aria-label="Permalink to &quot;从公司清单到投递清单&quot;">​</a></h2><ol><li>先选<a href="/shanghaitech-ic-wiki-dev.github.io/career/jobs">岗位方向</a>，写出自己能提供的能力证据。</li><li>从企业官网进入校园招聘页面，筛选城市、学历、届别和岗位要求。</li><li>记录投递日期、岗位编号、实际地点、面试状态和是否有排他承诺。</li><li>对照工作内容补项目与基础，不批量投递互不相关的职位。</li><li>接受意向前核对合同、培养安排、保密与知识产权，不依赖口头保证。</li></ol><p>薪资、招聘人数和转正比例均以当年信息为准，本站不做待遇排名。企业名录也不构成推荐或合作背书。</p><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/about/contribute">参与共建</a>补充有官网依据的上海企业与公开招聘入口，注明核实日期；请勿投稿私人内推联系方式、薪资排名或公司内部资料。</p></div><h2 id="地址与信息来源" tabindex="-1">地址与信息来源 <a class="header-anchor" href="#地址与信息来源" aria-label="Permalink to &quot;地址与信息来源&quot;">​</a></h2><ul><li><a href="https://www.unisoc.com/cn/about/contact-us" target="_blank" rel="noreferrer">紫光展锐：上海总部地址</a></li><li><a href="http://verisilicon.com/en/ContactUs" target="_blank" rel="noreferrer">芯原：总部及上海各办公点</a></li><li><a href="https://web.montage-tech.com/cn/Contact_Us" target="_blank" rel="noreferrer">澜起：总部地址</a></li><li><a href="https://www.huahonggrace.com/s/about_fab_shanghai_huali.php" target="_blank" rel="noreferrer">华虹：上海制造企业介绍</a></li><li>各企业技术与招聘信息以表中官方网站的最新介绍为准。</li></ul>',18)])])}const p=r(o,[["render",h]]);export{f as __pageData,p as default};
